INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('4b5c5369-5aee-46ec-8ffc-f9d119f6fa47', 'ce5645a6-4804-4745-a08f-5fc2ddc80faa', 'CO3119', 'Đồ án Mạng máy tính', 'Computer Networks Project', NULL, 'L.O.1', 'Từ vựng: Biết được một lượng từ vựng đủ để có thể diễn đạt ý mình về các chủ đề thường nhật như Bạn là ai, Trái tim ở đâu, Sức khỏe và hạnh phúc, Học tập và Gia đình & Bạn bè.', 'Vocabulary: Know a sufficient amount of vocabulary to be able to express yourself on everyday topics such as Who You Are, Where Your Heart Is, Health & Happiness, Study, and Family & Friends.', 1, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('df2691ce-d314-4015-bfbd-50c61b922453', 'ce5645a6-4804-4745-a08f-5fc2ddc80faa', 'CO3119', 'Đồ án Mạng máy tính', 'Computer Networks Project', NULL, 'L.O.2', 'Ngữ pháp: Biết được những cấu trúc ngữ pháp phổ biến và cần thiết, áp dụng được chúng trong các tình huống giao tiếp quen thuộc một cách hợp lý, chính xác.', 'Grammar: Know the common and necessary grammatical structures, apply them in familiar communication situations in a reasonable and accurate way.', 2, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('890829bc-2cd3-47c1-afb5-bf6e09af7a47', 'ce5645a6-4804-4745-a08f-5fc2ddc80faa', 'CO3119', 'Đồ án Mạng máy tính', 'Computer Networks Project', NULL, 'L.O.3', 'Nghe: Nghe hiểu được các thông tin rõ ràng, các ý chính cũng như chi tiết của những bài nói tương đối đơn giản về các chủ đề quen thuộc liên quan tới Bạn là ai, Trái tim ở đâu, Sức khỏe và hạnh phúc, Học tập và Gia đình & Bạn bè. Bên cạnh đó, có thể hiểu được những bài diễn thuyết, bài nói chuyện của các chuyên gia (nhà thuyết kế, ca sỹ, nhà khảo cổ học...) qua các bài TED Talks.', 'Listening: Can understand the clear information, main ideas and details of relatively simple talks on familiar topics related to Who You Are, Where Your Heart is, Health and Happiness, Study and Family & Friends. Besides, it is possible to understand the speeches and talks of experts (theoreticians, singers, archaeologists...) through TED Talks.', 3, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('0ed3b425-9ce2-4d8e-b69c-9c2034a0617c', 'ce5645a6-4804-4745-a08f-5fc2ddc80faa', 'CO3119', 'Đồ án Mạng máy tính', 'Computer Networks Project', NULL, 'L.O.4', 'Đọc: Đọc hiểu được ở mức độ nhất định những văn bản rõ ràng về các chủ đề liên quan cuộc sống thường nhật và các chủ đề trong các bài TED Talks.', 'Reading: Can read to a certain extent clear texts on topics related to everyday life and topics in TED Talks.', 4, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('82b313f7-2efc-4109-8459-c07d206ce673', 'ce5645a6-4804-4745-a08f-5fc2ddc80faa', 'CO3119', 'Đồ án Mạng máy tính', 'Computer Networks Project', NULL, 'L.O.5', 'Nói: Áp dụng được từ vựng và cấu trúc ngữ pháp, duy trì được sự trôi chảy của lời nói. Có thể nói về nhiều chủ đề khác nhau, diễn đạt các quan điểm rõ ràng, dễ hiểu.', 'Speaking: Apply vocabulary and grammatical structures, maintain fluency of speech. Can talk about a variety of topics, expressing opinions clearly and easily.', 5, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('a0cfb7cc-c881-475a-8bae-63e364bcd9ef', 'ce5645a6-4804-4745-a08f-5fc2ddc80faa', 'CO3119', 'Đồ án Mạng máy tính', 'Computer Networks Project', NULL, 'L.O.6', 'Viết: Áp dụng từ vựng và các cấu trúc để viết các văn bản rõ ràng, mạch lạc về các chủ đề quen thuộc.', 'Writing: Apply vocabulary and structures to write clear, coherent texts on familiar topics.', 6, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('ea57c5ce-74f7-40de-b240-b9c4def02301', '305e071f-be4c-47ca-9233-e9a4b5e489d8', 'CO3127', 'Đồ án tổng hợp - hướng kỹ thuật dữ liệu', 'Programming Intergration Project - Data', NULL, 'L.O.1', 'Từ vựng: Biết được một lượng từ vựng đủ để có thể diễn đạt ý mình về các chủ đề thường nhật như Bạn là ai, Trái tim ở đâu, Sức khỏe và hạnh phúc, Học tập và Gia đình & Bạn bè.', 'Vocabulary: Know a sufficient amount of vocabulary to be able to express yourself on everyday topics such as Who You Are, Where Your Heart Is, Health & Happiness, Study, and Family & Friends.', 1, NOW(), NOW());
