INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('f9c60a19-48c2-4cc5-acfc-5e85f3005127', '305e071f-be4c-47ca-9233-e9a4b5e489d8', 'CO3127', 'Đồ án tổng hợp - hướng kỹ thuật dữ liệu', 'Programming Intergration Project - Data', NULL, 'L.O.6', 'Viết: Áp dụng từ vựng và các cấu trúc để viết các văn bản rõ ràng, mạch lạc về các chủ đề quen thuộc.', 'Writing: Apply vocabulary and structures to write clear, coherent texts on familiar topics.', 6, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('e97aca72-270d-4d53-ae7f-56d600c17d58', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', NULL, 'L.O.1', 'Giải thích được các khái niệm cơ bản (dữ liệu, mô hình dữ liệu, cơ sở dữ liệu, hệ cơ sở dữ liệu, mô hình dữ liệu quan hệ, đại số quan hệ, SQL, các phương thức thiết kế cơ sở dữ liệu, mô hình thực thể mối liên kết, chuẩn hoá dữ liệu, các ứng dụng cơ sở dữ liệu), mô tả được kiến trúc của hệ cơ sở dữ liệu và các thành phần của một hệ cơ sở dữ liệu.', 'Explain basic concepts (data, data model, database, database system, the relational data model, the relational algebra, SQL, database design methodology, the entity relationship model, data normalization, database application), describe the architecture of a database system and the components of a database system.', 1, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('99a0d8ea-4644-4f22-be5f-9283d1ce642c', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'e97aca72-270d-4d53-ae7f-56d600c17d58', 'L.O.1.1', 'Giải thích được các khái niệm cơ bản: dữ liệu, cơ sở dữ liệu, hệ cơ sở dữ liệu, kiến trúc của hệ cơ sở dữ liệu và các thành phần của một hệ cơ sở dữ liệu', '– Explain basic concepts: data, database, database system, architecture of a database system and components of a database system', 2, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('15120855-b695-4735-896e-638681e978a5', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'e97aca72-270d-4d53-ae7f-56d600c17d58', 'L.O.1.2', 'Giải thích được mô hình dữ liệu quan hệ, đại số quan hệ, SQL', ' Explain the relational data model, relational algebra, and SQL', 3, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('8e192b63-a611-46d8-8dea-8f1c0eec7d92', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'e97aca72-270d-4d53-ae7f-56d600c17d58', 'L.O.1.3', 'Giải thích được các phương thức thiết kế cơ sở dữ liệu, mô hình thực thể mối liên kết, chuẩn hóa dữ liệu', 'Explain database design methodologies, entity relationship model, data normalization', 4, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('304fa194-491d-45fb-aa20-a3d960c380ab', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'e97aca72-270d-4d53-ae7f-56d600c17d58', 'L.O.1.4', 'Nêu ra được các ứng dụng của hệ cơ sở dữ liệu', 'Identify applications of database systems', 5, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('ca9f353c-fac6-42e8-88a9-8ab0116d9a7b', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', NULL, 'L.O.2', 'Thiết kế một cơ sở dữ liệu dùng mô hình thực thể mối liên kết, mô hình dữ liệu quan hệ và phương pháp thiết kế một cơ sở dữ liệu thoả mãn các yêu cầu dữ liệu của một ứng dụng cơ sở dữ liệu cụ thể.', 'Design a database using the entity relationship model, the relational data model and a database design methodology to meet data requirements of a particular database application.', 6, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('fe4e6ed3-c4e8-41b7-8b8d-f4f05cd79dd8', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'ca9f353c-fac6-42e8-88a9-8ab0116d9a7b', 'L.O.2.1', 'Thiết kế được lược đồ ý niệm dựa trên mô hình thực thể mối liên kết và các thể mở rộng của mô hình này thoả mãn các yêu cầu dữ liệu của một ứng dụng cơ sở dữ liệu cụ thể', ' Design a conceptual schema using the entity relationship model and its extended versions in such a way that data requirements of a given database application are satisfied.', 7, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('445c91ce-c3c3-468d-8001-794176cfed25', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'ca9f353c-fac6-42e8-88a9-8ab0116d9a7b', 'L.O.2.2', 'Phát triển được một lược đồ quan hệ từ lược đồ ý niệm đã được phát triển với mô hình thực thể mối liên kết và các thể mở rộng của mô hình này', 'Develop a relational schema from a conceptual schema which is designed using the entity relationship model and its extended versions', 8, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('fa649571-89db-470a-b3e5-9cff025b0957', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'ca9f353c-fac6-42e8-88a9-8ab0116d9a7b', 'L.O.2.3', 'Xác định được các phụ thuộc hàm của một quan hệ và xác định được khóa của một quan hệ với một tập phụ thuộc hàm cho trước', 'Identify functional dependencies of a relation and define a key of a relation with given functional dependencies', 9, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('01ccc997-1baf-4718-b457-52f539d3dfe3', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', 'ca9f353c-fac6-42e8-88a9-8ab0116d9a7b', 'L.O.2.4', 'Xác định được dạng chuẩn (1NF, 2NF, 3NF, BCNF) của một quan hệ dựa trên khóa chính và tập phụ thuộc hàm cho trước', 'Determine a normal form (1NF, 2NF, 3NF, BCNF) of a relation based on its given primary key and functional dependencies ', 10, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('43e5bd2d-0d8a-4391-8861-65021f60355f', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', NULL, 'L.O.3', 'Dùng ngôn ngữ SQL và quản lý cơ sở dữ liệu trên các hệ quản trị cơ sở dữ liệu sẵn có như MySQL, Oracle, và MS SQL Server.', 'Use SQL and manage databases on an existing relational database management system (DBMS) such as MySQL, Oracle, and MS SQL Server.', 11, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('1434584e-5acc-4ed6-8dc5-80e0a04c6d12', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '43e5bd2d-0d8a-4391-8861-65021f60355f', 'L.O.3.1', 'Viết được các câu lệnh định nghĩa và thao tác (truy vấn, thêm mới, xóa, và cập nhật) dữ liệu cũng như các thủ tục/hàm/trigger xử lý với ngôn ngữ SQL', 'Write data definition and manipulation (query, insertion, deletion, and update) statements as well as procedures/functions/triggers for data processing in SQL', 12, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('53d2d76c-d10b-41ed-bb1b-5bdab00a0e4a', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '43e5bd2d-0d8a-4391-8861-65021f60355f', 'L.O.3.2', 'Cài đặt và cấu hình được một hệ quản trị cơ sở dữ liệu sẵn có như MySQL, Oracle, và MS SQL Server', 'Install and configure an existing database management system such as MySQL, Oracle, and MS SQL Server', 13, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('70d6fe98-394a-4e31-91fb-5c4d8bb64855', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '43e5bd2d-0d8a-4391-8861-65021f60355f', 'L.O.3.3', 'Hiện thực và quản lý cơ sở dữ liệu cho các ứng dụng cơ sở dữ liệu trên nền tảng một hệ quản trị cơ sở dữ liệu sẵn có', 'Implement and manage databases for database applications on top of an existing database management system ', 14, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('e36aed08-1b11-4473-bc2b-fe4d39202776', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '43e5bd2d-0d8a-4391-8861-65021f60355f', 'L.O.3.4', 'Sử dụng các kỹ thuật bảo mật cơ bản như phân quyền và quản lý người dùng trên nền tảng một hệ quản trị cơ sở dữ liệu sẵn có', 'Use basic security techniques such as authorization and user management on an existing database management system ', 15, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('59572bfd-0a36-4896-a465-db9c7fff6111', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', NULL, 'L.O.4', 'Có khả năng phân tích sự đánh đổi giữa tính hữu dụng, hiệu năng, bảo mật và các ràng buộc về tài nguyên và công nghệ để xác định được cách tiếp cận phù hợp, hiệu quả cho việc thiết kế, và quản lý dữ liệu cho các ứng dụng trong một hệ thống thông tin: dựa trên xử lý tập tin hay cách tiếp cận CSDL, các mô hình dữ liệu và hệ quản trị cơ sở dữ liệu nào phù hợp.', 'Be able to analyze tradeoffs between usability, performance, security and constraints of resource and technology in order to identify an appropriate approach for data design and implementation (file based approach or database approach, relational data model or other data models, approaches for database management systems). ', 16, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('7f0fcb86-d282-4e2a-80a5-de1274d02c59', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '59572bfd-0a36-4896-a465-db9c7fff6111', 'L.O.4.1', 'Giải thích được các đặc điểm phân biệt hướng tiếp cận cơ sở dữ liệu với hướng tiếp cận xử lý tập tin', 'Explain the characteristics that distinguish the database approach from the approach of programming with data files', 17, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('ccdbfa8a-48bc-401c-910a-8f6aa305bbd4', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '59572bfd-0a36-4896-a465-db9c7fff6111', 'L.O.4.2', 'Giải thích được khái niệm độc lập dữ liệu và sự quan trọng của độc lập dữ liệu trong hệ cơ sở dữ liệu', '– Explain the concept of data independence and its importance in a database system', 18, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('f29173c5-a989-4bc7-a2d0-ce83b977f6b9', 'a83396c1-a1a5-4047-9de4-c6a36bd46ce7', 'CO2013', 'Hệ cơ sở Dữ liệu', 'Database Systems', '59572bfd-0a36-4896-a465-db9c7fff6111', 'L.O.4.3', 'Đánh giá sự phù hợp và hiệu quả của cách tiếp cận cơ sở dữ liệu, các mô hình dữ liệu và hệ quản trị cơ sở dữ liệu cho các ứng dụng trong một hệ thống thông tin', 'Evaluate appropriateness and effectiveness of database approaches, data models and database management systems for developing applications in an information system', 19, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('a07578fb-90b1-464c-9fcc-bfa1b99f81cc', 'a9f31aac-5baf-4e51-ae19-b1ae1ce02cf8', 'CO2039', 'Lập trình Nâng cao', 'Advanced Programming', NULL, 'L.O.1', 'Trình bày được các kiến thức thiết yếu về mô hình hướng đối tượng như class,object, bao đóng, thừa kế, bao gộp, gởi thông điệp, đa xạ, tổng quát hóa, Các mẫu thiết kế cơ bản... cũng như các kiến thức cơ bản liên quan đến lập trình hướng chức năng (FP)', 'Present the fundamental knowledges of object-oriented model such as class, object closure, inheritance, inclusion, sending messages, polymophism, generalization, design patterns as well as basic knowledges related to functional programming (FP', 1, NOW(), NOW());
