INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('c8b39ed6-1e35-40aa-a163-de19915d12ad', '98cb2a12-02af-460c-9888-0800e16e3934', 'CO2007', 'Kiến trúc máy tính', '', 'c3aa9fce-9edc-42b0-96a9-e53860f66e37', 'L.O.5.2', 'Viết chương trình đơn giản bằng hợp ngữ để hiện thực một giải thuật cơ bản 5.Phương thức giảng dạy và học tập (Teaching and assessment methods) 5.1.Phương thức giảng dạy (Teaching methods) STT Phương thức giảng dạy 1 Phương pháp học tập tích hợp 5.2.Phương pháp giảng dạy (Teaching activities) Loại hoạt động Tên loại hoạt động Nội dung class ) exercises) report) ) exam) 5.3.Hình thức đánh giá (Assessment methods) Chuẩn đầu ra chi tiết Hoạt động đánh giá memory in different methods) specific organization parameters and methods) cache memory, main memory, and secondary memory) interact with the user) implement a basic algorithm) 5.4.Hướng dẫn cách học (Study guidelines) • Hướng dẫn cách học: • Tài liệu (slide bài giảng) được đưa lên BKeL hàng tuần. Sinh viên tải về, in ra và mang theo khi lên lớp học. • Sinh viên nên đi học đầy đủ và làm bài tập trong quá trình học sẽ giúp tiết kiệm thời gian trong quá trình ôn thi giữa kỳ và cuối kỳ. • Đối với phần thực hành, sinh viên tham gia đầy đủ các buổi thí nghiệm và nộp lại báo cáo thí nghiệm ngay cuối giờ thí nghiệm. • Instruction on how to learn: • Materials (lecture slides) are uploaded to BKeL weekly. Students download, print, and bring with them to class. • Students should attend school fully and do homework during the study, which will save time during midterm and final exam review. • For the practical part, students participate fully in the experimental sessions and return the lab report at the end of the experiment. 6.Nội dung chi tiết của học phần (Course content) L.O. Chuẩn đầu ra chi tiết (Detailed learning outcomes) A. Hoạt động đánh giá (Assessment activity) Lec. Hoạt động dạy Giảng viên (Lecturer) Stu. Hoạt động học Sinh viên (Student) Buổi Nội dung (Content) Hoạt động dạy và học (Lecturing) 1.1. Lịch sử phát triển Lec: Thuyết giảng và giao bài tập 1.2. Các thành phần chính và chức năng hoạt động (Lectures and assignments) 1.3. Hiệu suất: Đo đạc & Đánh giá Stu: Nghe giảng và làm bài tập 1.1. Development history Lec: Thuyết giảng và giao bài tập 1.2. Main components and active functions ( Lectures and assignments) 1.3. Performance: Measurement & Evaluation) Stu: Nghe giảng và làm bài tập Lec: Thuyết giảng và giao bài tập Stu: Nghe giảng và làm bài tập 2.2. Nguyên tắc thiết kế Lec: Thuyết giảng và giao bài tập 2.3. Cấu trúc lệnh (MIPS) (Lectures and assignments) 2.4. Địa chỉ hóa Stu: Nghe giảng và làm bài tập 2.5. Tổ chức dù liệu trong bộ nhớ (Listen to lectures and do exercises) 2.7. Các lệnh rẽ nhánh Lec: Thuyết giảng và giao bài tập 2.8. Trình con (Lectures and assignments) 2.9. Dữ liệu phi số Stu: Nghe giảng và làm bài tập 2.10. Biên dịch ngôn ngữ cấp cao và thực thi chương trình (Listen to lectures and do exercises) 2.3. Instruction Structure (MIPS) Stu: Nghe giảng và làm bài tập 2.4. Addressing (Listen to lectures and do exercises) 2.6. Data transport commands Lec: Thuyết giảng và giao bài tập 2.7. Branching Instructions ( Lectures and assignments) 2.8. Subroutine Stu: Nghe giảng và làm bài tập 2.9. Non-numeric data (Listen to lectures and do exercises) program) Lec: Thuyết giảng và giao bài tập Stu: Nghe giảng và làm bài tập 3.1. Biểu diễn số: có dấu và không dấu Lec: Thuyết giảng và giao bài tập 3.2. Các phép tính số học: Cộng, Trừ nhị phân ( Lectures and assignments) 3.3. Các phép luận lý Stu: Nghe giảng và làm bài tập 3.4. Xây dựng đơn vị Số học – Luận lý (Listen to lectures and do exercises) 3.6. Các phếp tính số thực Lec: Thuyết giảng và giao bài tập 3.3. Logic spells Lec: Thuyết giảng và giao bài tập 3.4. Building Arithmetic – Logical units