INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('a0cb6837-83e6-4496-8410-baef59d87a09', 'e38bbd83-da77-406f-ac3a-4a4b6ed3a5d5', 'CO2017', 'Hệ điều hành', '', '7b70a900-7aec-4416-819d-36f8968c310d', 'L.O.1.1', 'Định nghĩa được các chức năng và cấu trúc của một hệ điều hành hiện đại theo nhu cầu cụ thể nào đó', 'Define functionality and structures that a modern operating system must deliver to meet a particular need.', 2, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('6628a711-9717-4574-87ec-322688a487fd', 'e38bbd83-da77-406f-ac3a-4a4b6ed3a5d5', 'CO2017', 'Hệ điều hành', '', '7b70a900-7aec-4416-819d-36f8968c310d', 'L.O.1.3', 'Giải thích bộ nhớ ảo và hiện thực cả về phần cứng lẫn phần mềm.', 'Explain virtual memory and its realization in hardware and software.', 3, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('8bcd491d-0aa9-4d45-9d65-e648bb39efd2', 'e38bbd83-da77-406f-ac3a-4a4b6ed3a5d5', 'CO2017', 'Hệ điều hành', '', NULL, 'L.O.2', 'Mối quan hệ giữa hiệu suất và các hạn chế về tài nguyên và công nghệ trong một thiết kế của một hệ điều hành.', 'Able to report the tradeoffs between the performance and the resource and technology constraints in a design of an operating system.', 4, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('40ed6529-2bda-40ac-a10e-73a15bc3b0e9', 'e38bbd83-da77-406f-ac3a-4a4b6ed3a5d5', 'CO2017', 'Hệ điều hành', '', '8bcd491d-0aa9-4d45-9d65-e648bb39efd2', 'L.O.2.1', 'So sánh và làm nổi bật các giải thuật thông dụng để định thời công việc trong hệ điều hành', 'Compare and contrast common algorithms used for both preemptive and non-preemptive scheduling of tasks in operating systems.', 5, NOW(), NOW());
