INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('21bc6869-f1fb-4b4b-b742-b604d47c0de2', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', NULL, 'L.O.4', 'Sử dụng các kỹ thuật liên quan xử lý giao tác, điều khiển tương tranh và khôi phục dữ liệu để giải quyết các sự cố có thể xảy ra làm dữ liệu không nhất quán và mất mát cũng như xử lý dữ liệu trong môi trường đa người dùng đồng thời.', ' Use several techniques related to transaction processing, concurrency control, database recovery to manage data when there is a system crash as well as to manage data in a concurrent multi-user environment for no data inconsistency and loss.', 10, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('d74f050a-3e04-4ee9-a103-b5e7e66a34bf', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '21bc6869-f1fb-4b4b-b742-b604d47c0de2', 'L.O.4.1', 'Thao tác với giao tác và lịch biểu.', 'Manipulate transactions and their schedules.', 11, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('44da1bf4-de89-456e-8582-f7938ecbc3ab', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '21bc6869-f1fb-4b4b-b742-b604d47c0de2', 'L.O.4.2', 'Sử dụng các kỹ thuật điều khiển tương tranh để xử lý dữ liệu trong môi trường đa người dùng đồng thời.', 'Use concurrency control techniques to manage data in a concurrent multi-user environment.', 12, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('1f511f81-035a-4cd2-b8f4-a0854b95fb4d', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '21bc6869-f1fb-4b4b-b742-b604d47c0de2', 'L.O.4.3', 'Sử dụng các kỹ thuật điều khiển tương tranh để xử lý dữ liệu trong môi trường đa người dùng đồng thời.', 'Use database recovery techniques to manage data when there is a system crash.', 13, NOW(), NOW());
