INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('a9171ee8-735e-48f1-acd3-0e08b2f6c7bd', '5926a8be-128d-422b-80c5-878228d19774', 'CO3023', 'Cơ sở dữ liệu phân tán và hướng đối tượng', '', NULL, 'L.O.2', 'Nắm được các vấn đề và thách thức phải đối mặt trong thiết kế hệ thống cơ sở dữ liệu phân tán Hiểu rõ các nguyên tắc cơ bản và kiến trúc của các hệ thống cơ sở dữ liệu phân tán.', 'Capture faced issues and challenges while designing distributed database systems. Understand fundamental principles and architecture of distributed database systems.', 2, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('4d996b81-61c1-480a-a71a-ae604b438a89', '5926a8be-128d-422b-80c5-878228d19774', 'CO3023', 'Cơ sở dữ liệu phân tán và hướng đối tượng', '', NULL, 'L.O.3', 'Nắm vững các chiến lược lựa chọn kế hoạch thực hiện truy vấn được tối ưu hoá cho các truy vấn dữ liệu phân tán.', 'Understand strategies to optimize distributed database systems.', 3, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('af07792d-05b7-45eb-8f98-0d48eabd664e', '5926a8be-128d-422b-80c5-878228d19774', 'CO3023', 'Cơ sở dữ liệu phân tán và hướng đối tượng', '', '4d996b81-61c1-480a-a71a-ae604b438a89', 'L.O.3.1', 'Nắm vững các chiến lược lựa chọn kế hoạch thực hiện truy vấn được tối ưu hoá cho các truy vấn dữ liệu phân tán.', 'Develop the understanding of choosing the optimized query execution plan for distributed queries', 4, NOW(), NOW());
