INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('b7d3b539-b9c5-4760-8155-5912df0809bc', '2ef48aca-d80c-42e0-8eaa-eb18cabc4be6', 'CO3033', 'Bảo mật hệ thống thông tin', '', NULL, 'L.O.1', 'Nhận dạng, hiểu, và phân tích được các yêu cầu về bảo mật hệ thống thông tin của một tổ chức. Nắm được những kiến thức cơ bản về các cơ chế, mô hình và kỹ thuật để giữ bí mật, bảo đảm tính toàn vẹn và sẵn sàng trong các hệ thống thông tin và các hệ CSDL.', 'Define basic concepts commonly used in the area of information systems security', 1, NOW(), NOW());
