INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('5f278067-8214-4d72-bb16-e3c4fb43ee71', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '7e2d3040-a72e-4d6e-b810-4f41b64c022a', 'L.O.2.1', 'Thao tác các tiện ích về tổ chức lưu trữ vật lý và các cấu trúc tập tin.', 'Manipulate the facilities for disk storage and file structures.', 5, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('4f7b67b8-bbdd-4337-85b0-31f6e82db254', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '7e2d3040-a72e-4d6e-b810-4f41b64c022a', 'L.O.2.2', 'Sử dụng các cấu trúc chỉ mục trong các ứng dụng thực tiễn.', 'Use some typical index structures in practical applications.', 6, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('1c87d2c3-4009-4660-8d14-83409cf35f69', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', NULL, 'L.O.3', 'Thực hành xử lý và tối ưu hóa truy vấn trên các hệ quản trị cơ sở dữ liệu quan hệ với ngôn ngữ SQL.', ' Practice query processing and optimization of a relational database management system with SQL language.', 7, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('b1b15dd4-7e01-4a6b-95ca-95a091f772a7', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '1c87d2c3-4009-4660-8d14-83409cf35f69', 'L.O.3.1', 'Diễn tả các bước trong quá trình xử lý và tối ưu truy vấn với các dạng câu truy vấn tiêu biểu như chọn, chiếu, kết, ...', 'Illustrate the typical steps when processing and optimizing a high-level query for selection, projection, and join.', 8, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('643293ed-3cbc-4fc2-8c8d-224d70b75e81', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', '1c87d2c3-4009-4660-8d14-83409cf35f69', 'L.O.3.2', 'Thực hiện tối ưu truy vấn dựa vào quá trình tối ưu truy vấn phổ biến cho các dạng câu truy vấn tiêu biểu như chọn, chiếu, kết, ....', 'Produce a query plan of a typical high-level query for selection and join using a popular query optimizer.', 9, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('d0132021-39b9-43bb-ac61-599eb51fdc45', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', NULL, 'L.O.4', 'Sử dụng các kỹ thuật liên quan xử lý giao tác, điều khiển tương tranh và khôi phục dữ liệu để giải quyết các sự cố có thể xảy ra làm dữ liệu không nhất quán và mất mát cũng như xử lý dữ liệu trong môi trường đa người dùng đồng thời.', ' Use several techniques related to transaction processing, concurrency control, database recovery to manage data when there is a system crash as well as to manage data in a concurrent multi-user environment for no data inconsistency and loss.', 10, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('05232cd0-86fd-4519-a5c5-185b1f6f88d6', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', 'd0132021-39b9-43bb-ac61-599eb51fdc45', 'L.O.4.1', 'Thao tác với giao tác và lịch biểu.', 'Manipulate transactions and their schedules.', 11, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('2f67a416-e187-42c7-b04c-03745196c1ab', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', 'd0132021-39b9-43bb-ac61-599eb51fdc45', 'L.O.4.2', 'Sử dụng các kỹ thuật điều khiển tương tranh để xử lý dữ liệu trong môi trường đa người dùng đồng thời.', 'Use concurrency control techniques to manage data in a concurrent multi-user environment.', 12, NOW(), NOW());
INSERT INTO course_management.subject_learning_outcomes (subject_learning_outcomes_id, subject_id, subject_code, subject_name, subject_name_en, subject_learning_outcomes_parent_id, code, description, description_en, display_order, created_at, updated_at) VALUES ('08752c29-e7b5-48a9-b4af-5b1e2f02497f', '55a95dba-54b9-438c-9f4e-71c1d516d116', 'CO3021', 'Hệ quản trị cơ sở dữ liệu', '', 'd0132021-39b9-43bb-ac61-599eb51fdc45', 'L.O.4.3', 'Sử dụng các kỹ thuật điều khiển tương tranh để xử lý dữ liệu trong môi trường đa người dùng đồng thời.', 'Use database recovery techniques to manage data when there is a system crash.', 13, NOW(), NOW());
