    (gen_random_uuid(), 'c1bc6b66-cc13-4ee8-9c21-c0da751dd0c2', 'CO3011', 'Quản lý Dự án Phần mềm', 'Software Project Management', NULL, 'L.O.2', 'Sử dụng được các công cụ chuyên dụng để quản lý phần mềm.', 'Use specialized tools to manage software', 2, '2025-12-03 23:05:17.725+07', '2025-12-03 23:05:17.725+07');
INSERT INTO course_management.subject_learning_outcomes
