    (gen_random_uuid(), '5c05d0ce-0659-4f71-80e0-aaefe10313e2', 'CO3133', 'Học sâu và Ứng dụng', 'Deep Learning and Its Applications', NULL, 'L.O.1', 'Hiểu, phân tích, điều chỉnh và sáng tạo các kiến trúc mạng nơron học sâu.', 'Understand, analyze, modify, and create deep learning neural network architectures.', 1, '2025-12-03 23:05:17.725+07', '2025-12-03 23:05:17.725+07'),
    (gen_random_uuid(), '5c05d0ce-0659-4f71-80e0-aaefe10313e2', 'CO3133', 'Học sâu và Ứng dụng', 'Deep Learning and Its Applications', NULL, 'L.O.2', 'Tổ chức dữ liệu và nhãn, cũng như các giải thuật và quy trình huấn luyện mạng nơron học sâu.', 'Organize data and labeling, as well as algorithms and training processes for deep learning neural networks.', 2, '2025-12-03 23:05:17.725+07', '2025-12-03 23:05:17.725+07');
INSERT INTO course_management.subject_learning_outcomes
