VALUES
    (gen_random_uuid(), 'f565edde-f4a0-4222-8f9f-4854a7f3d151', 'CO3135', 'Lập trình cho Trí tuệ nhân tạo và Khoa học dữ liệu', 'Programming for Artificial Intelligence and Data Science', NULL, 'L.O.1', 'Biểu diễn và xử lý dữ liệu ở dạng ma trận nhiều chiều và dạng bảng với các thư viện lập trình như Numpy, Pytorch, Tensorflow và Pandas.', 'Represent and process data using multi-dimensional arrays and Dataframes with programming libraries such as Numpy, Pytorch, Tensorflow, and Pandas.', 1, '2025-12-03 23:05:17.725+07', '2025-12-03 23:05:17.725+07'),
    (gen_random_uuid(), 'f565edde-f4a0-4222-8f9f-4854a7f3d151', 'CO3135', 'Lập trình cho Trí tuệ nhân tạo và Khoa học dữ liệu', 'Programming for Artificial Intelligence and Data Science', NULL, 'L.O.2', 'Hiển thị trực quan dữ liệu, chuẩn bị dữ liệu đầu vào và phân tích kết quả đầu ra để xây dựng chương trình phân tích dữ liệu.', 'Visualize data, prepare input data, and analyze output results to consolidate skills into a complete data analysis program.', 2, '2025-12-03 23:05:17.725+07', '2025-12-03 23:05:17.725+07');